package lifequest.dashboard;
import lifequest.Main;import lifequest.analytics.AnalyticsPanel;import lifequest.history.HistoryPanel;import lifequest.model.User;import lifequest.profile.ProfilePanel;import lifequest.quests.QuestPanel;import lifequest.settings.SettingsPanel;import lifequest.ui.Style;import javax.swing.*;import java.awt.*;
public class DashboardPanel extends JPanel {
 private final Main main;private final User user;private final JPanel content=new JPanel(new BorderLayout());
 public DashboardPanel(Main m,User u){main=m;user=u;setLayout(new BorderLayout());setBackground(Style.BACKGROUND);add(sidebar(),BorderLayout.WEST);content.setBackground(Style.BACKGROUND);add(content,BorderLayout.CENTER);dashboard();}
 private JPanel sidebar(){JPanel s=new JPanel();s.setBackground(Style.SIDEBAR);s.setPreferredSize(new Dimension(205,0));s.setLayout(new BoxLayout(s,BoxLayout.Y_AXIS));s.setBorder(BorderFactory.createEmptyBorder(20,12,20,12));s.add(Style.title("LIFEQUEST"));s.add(Box.createVerticalStrut(25));nav(s,"Dashboard",e->dashboard());nav(s,"Quests",e->show(new QuestPanel(main,user)));nav(s,"History",e->show(new HistoryPanel(user)));nav(s,"Analytics",e->show(new AnalyticsPanel(user)));nav(s,"Profile",e->show(new ProfilePanel(user)));nav(s,"Settings",e->show(new SettingsPanel(main,user)));s.add(Box.createVerticalGlue());nav(s,"Logout",e->main.logout());return s;}
 private void nav(JPanel s,String t,java.awt.event.ActionListener a){JButton b=new JButton(t);b.setAlignmentX(Component.LEFT_ALIGNMENT);b.setMaximumSize(new Dimension(190,40));b.setHorizontalAlignment(SwingConstants.LEFT);b.addActionListener(a);s.add(b);s.add(Box.createVerticalStrut(5));}
 private void show(JPanel p){content.removeAll();content.add(p);content.revalidate();content.repaint();}
 private void dashboard(){content.removeAll();JPanel p=new JPanel(new BorderLayout(15,15));p.setBackground(Style.BACKGROUND);p.setBorder(BorderFactory.createEmptyBorder(28,30,28,30));p.add(Style.title("Welcome, "+user.getUsername()),BorderLayout.NORTH);JPanel cards=new JPanel(new GridLayout(1,4,12,12));cards.setOpaque(false);cards.add(card("Level",""+user.getLevel()));cards.add(card("XP",""+user.getXp()));cards.add(card("Coins",""+user.getCoins()));cards.add(card("Focus",""+user.getFocus()));p.add(cards,BorderLayout.CENTER);JPanel info=Style.card();info.setLayout(new BoxLayout(info,BoxLayout.Y_AXIS));info.add(Style.title("Character Stats"));info.add(Style.label("Health: "+user.getHealth()));info.add(Style.label("Focus: "+user.getFocus()));info.add(Style.label("Discipline: "+user.getDiscipline()));info.add(Style.label("Strength: "+user.getStrength()));JProgressBar bar=new JProgressBar(0,100);bar.setValue(user.getXp()%100);bar.setStringPainted(true);bar.setString("XP to next level: "+user.getXp()%100+"/100");bar.setForeground(Style.ACCENT);info.add(Box.createVerticalStrut(12));info.add(bar);p.add(info,BorderLayout.SOUTH);content.add(p);content.revalidate();content.repaint();}
 private JPanel card(String n,String v){JPanel p=Style.card();p.setLayout(new BorderLayout());JLabel a=Style.label(n);a.setForeground(Style.MUTED);p.add(a,BorderLayout.NORTH);p.add(Style.title(v),BorderLayout.CENTER);return p;}
}
